        return 0 if a[0] == 1 else -1

    # Check if it's possible to make all elements 1
    total_gcd = a[0]
    for i in range(1, n):
        total_gcd = gcd(total_gcd, a[i])
    if total_gcd != 1:
        return -1

    # Dynamic programming approach
    @lru_cache(None)
    def dp(i, j):
        if i == j:
            return 0
        if i + 1 == j:
            return 1 if a[i] == 1 or a[j] == 1 else 2

        res = float('inf')
        for k in range(i, j):
            res = min(res, dp(i, k) + dp(k + 1, j))

        if gcd(a[i], a[j]) == 1:
            res = min(res, dp(i + 1, j - 1) + 1)

        return res

    return dp(0, n - 1)

